import React, { useEffect, useState } from 'react';
import TaskForm from '../components/TaskForm';
import TaskCard from '../components/TaskCard';
import api from '../services/api';

export default function Home() {
  const [tasks, setTasks] = useState([]);
  const [editing, setEditing] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchTasks = async () => {
    try {
      setLoading(true);
      const res = await api.get('/tasks');
      setTasks(res.data || []);
    } catch (err) {
      console.error('Fetch tasks error', err);
      alert('Could not fetch tasks. Is backend running?');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  const addTask = async (payload) => {
    await api.post('/tasks', payload);
    fetchTasks();
  };

  const updateTask = async (id, payload) => {
    await api.put(`/tasks/${id}`, payload);
    setEditing(null);
    fetchTasks();
  };

  const deleteTask = async (id) => {
    if (!window.confirm('Delete this task?')) return;
    await api.delete(`/tasks/${id}`);
    fetchTasks();
  };

  const toggleComplete = async (task) => {
    await api.put(`/tasks/${task.id}`, { completed: !task.completed });
    fetchTasks();
  };

  return (
    <div>
      <TaskForm
        onSubmit={addTask}
        editing={editing}
        onUpdate={updateTask}
        onCancel={() => setEditing(null)}
      />

      <div className="mt-6">
        {loading && <div className="text-sm text-gray-500">Loading tasks...</div>}
        {!loading && tasks.length === 0 && <div className="text-gray-500">No tasks yet — create one!</div>}

        <div className="mt-4 space-y-3">
          {tasks.map((t) => (
            <TaskCard
              key={t.id}
              task={t}
              onEdit={() => setEditing(t)}
              onDelete={() => deleteTask(t.id)}
              onToggleComplete={() => toggleComplete(t)}
            />
          ))}
        </div>
      </div>
    </div>
  );
}
